require('dotenv').config();
const mongoose = require('mongoose');
const Case = require('./models/Case');

const PHOTO = 'data:image/jpeg;base64,';

async function addTestCase() {
  await mongoose.connect(process.env.MONGO_URI);
  console.log('✅ Connected');

  // Remove old test entry if exists
  await Case.deleteOne({ report_number: 'TB-TEST-0001' });

  const saved = await Case.create({
    report_number:      'TB-TEST-0001',
    full_name:          'Aswin Pal Raj',
    age:                21,
    gender:             'Male',
    status:             'missing',
    last_seen_location: 'Chennai, Tamil Nadu',
    last_seen_date:     '2026-03-17',
    last_seen_time:     '11:00',
    last_seen_wearing:  'Printed shirt, red lanyard',
    height:             '5.6ft - 5.8ft',
    complexion:         'Dark',
    hair_color:         'Black',
    blood_group:        'Unknown',
    description:        'TEST CASE — Face scan demo person.',
    photo:              PHOTO,
    reporter_name:      'Family Contact',
    reporter_phone:     '9999999999',
    reporter_email:     'test@traceback.com',
    reporter_relation:  'Friend',
    police_station:     'Chennai Central PS',
    police_email:       'police@traceback.com',
  });

  console.log('✅ Test case added:', saved.report_number);
  console.log('   Name:', saved.full_name);
  console.log('   Photo: YES (' + Math.round(PHOTO.length/1024) + ' KB)');
  console.log('');
  console.log('Now open Face Scan and point the camera at this person!');
  await mongoose.disconnect();
}

addTestCase().catch(e => { console.error('❌', e.message); process.exit(1); });
